const resultats = normalizeBrowserlessResult($input.first().json);

if (resultats.statut_session === "invalide") {
  throw new Error(resultats.erreur || "Session Bubble invalide");
}

const captures = resultats.captures || {};
const seriesMap = {};

function normalizeBrowserlessResult(value) {
  let data = value;

  if (typeof data === "string") {
    try {
      data = JSON.parse(data);
    } catch (error) {
      return {};
    }
  }

  if (data && typeof data.data === "string") {
    try {
      data = JSON.parse(data.data);
    } catch (error) {
      return {};
    }
  } else if (
    data &&
    data.data &&
    typeof data.data === "object" &&
    !data.captures
  ) {
    data = data.data;
  }

  return data || {};
}

function decodeHtml(value) {
  return String(value || "")
    .replace(/&nbsp;|&#160;|&#xA0;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/\s+/g, " ")
    .trim();
}

function parseCountPair(value) {
  const text = String(value || "");
  const match = text.match(/([0-9]+)(?:\s*\/\s*([0-9]+))?/);

  return {
    current: match ? parseInt(match[1], 10) : 0,
    total: match && match[2] ? parseInt(match[2], 10) : 0
  };
}

function ensureSerie(id, categorie) {
  if (!seriesMap[id]) {
    seriesMap[id] = {
      id_unique: id,
      titre: "Titre inconnu",
      categorie: categorie || "Autre",
      albums_possedes: 0,
      albums_lus_possedes: 0,
      albums_non_possedes_lu: 0,
      albums_manquants: 0,
      nb_dedicace: 0
    };
  }

  if (categorie && categorie !== "Autre") {
    seriesMap[id].categorie = categorie;
  } else if (!seriesMap[id].categorie) {
    seriesMap[id].categorie = "Autre";
  }

  return seriesMap[id];
}

function getTitle(block) {
  const patterns = [
    /<div[^>]*class="[^"]*tw:truncate[^"]*tw:font-bold[^"]*"[^>]*>\s*([^<]+?)\s*<\/div>/i,
    /<div[^>]*class="[^"]*font-bold[^"]*"[^>]*>\s*([^<]+?)\s*<\/div>/i,
    /fw-bold[^>]*>\s*([^<]+?)\s*<\/div>/i
  ];

  for (const pattern of patterns) {
    const match = block.match(pattern);

    if (match) {
      return decodeHtml(match[1]);
    }
  }

  return "Titre inconnu";
}

function getAlbumCount(block) {
  const patterns = [
    /<div[^>]*>\s*([0-9]+(?:\s*\/\s*[0-9]+)?)\s*<\/div>\s*<div[^>]*>\s*albums?\s*<\/div>/i,
    /([0-9]+(?:\s*\/\s*[0-9]+)?)\s+albums?/i
  ];

  for (const pattern of patterns) {
    const match = block.match(pattern);

    if (match) {
      return parseCountPair(match[1]);
    }
  }

  return {
    current: 0,
    total: 0
  };
}

function getReadCount(block) {
  const patterns = [
    /<div[^>]*>\s*([0-9]+(?:\s*\/\s*[0-9]+)?)\s*<\/div>\s*<div[^>]*>\s*lus?\s*<\/div>/i,
    /([0-9]+(?:\s*\/\s*[0-9]+)?)\s+lus?/i
  ];

  for (const pattern of patterns) {
    const match = block.match(pattern);

    if (match) {
      return parseCountPair(match[1]);
    }
  }

  return {
    current: 0,
    total: 0
  };
}

function getDedicaceCount(block) {
  const patterns = [
    /<div[^>]*>\s*([0-9]+)\s*<\/div>\s*<div[^>]*>\s*dédicaces?\s*<\/div>/i,
    /([0-9]+)\s+dédicaces?/i,
    /([0-9]+)\s+dédicace/i
  ];

  for (const pattern of patterns) {
    const match = block.match(pattern);

    if (match) {
      return parseInt(match[1], 10) || 0;
    }
  }

  return 0;
}

function scanSeriesLinks(html, callback) {
  if (!html) return;

  const morceaux = String(html).split('href="/');

  for (let i = 1; i < morceaux.length; i++) {
    const block = morceaux[i];

    const idMatch = block.match(/^[^"\/]+\/serie\/([a-zA-Z0-9]+)"/);

    if (!idMatch) continue;

    callback(idMatch[1], block);
  }
}

function parsePossessedCapture(captureKey, categorie) {
  const html = captures?.[captureKey]?.html || "";

  scanSeriesLinks(html, (id, block) => {
    const serie = ensureSerie(id, categorie);

    const titre = getTitle(block);

    if (titre && titre !== "Titre inconnu") {
      serie.titre = titre;
    }

    const albums = getAlbumCount(block);
    const lus = getReadCount(block);
    const dedicaces = getDedicaceCount(block);

    if (albums.current > 0) {
      serie.albums_possedes = Math.max(serie.albums_possedes, albums.current);
    }

    if (lus.current > 0) {
      serie.albums_lus_possedes = Math.max(serie.albums_lus_possedes, lus.current);
    }

    if (albums.total > 0) {
      const manquants = Math.max(albums.total - albums.current, 0);
      serie.albums_manquants = Math.max(serie.albums_manquants, manquants);
    }

    if (dedicaces > 0) {
      serie.nb_dedicace = Math.max(serie.nb_dedicace, dedicaces);
    }
  });
}

function parseNonPossessedReadCapture(captureKey, categorie) {
  const html = captures?.[captureKey]?.html || "";

  scanSeriesLinks(html, (id, block) => {
    const serie = ensureSerie(id, categorie);

    const titre = getTitle(block);

    if (titre && titre !== "Titre inconnu") {
      serie.titre = titre;
    }

    const lus = getReadCount(block);
    const albums = getAlbumCount(block);

    const nonPossedesLus = Math.max(lus.current, albums.current, 0);

    if (nonPossedesLus > 0) {
      serie.albums_non_possedes_lu = Math.max(
        serie.albums_non_possedes_lu,
        nonPossedesLus
      );
    }

    if (albums.total > 0) {
      const manquants = Math.max(albums.total - albums.current, 0);
      serie.albums_manquants = Math.max(serie.albums_manquants, manquants);
    }
  });
}

function parseDedicaceCapture(captureKey) {
  const html = captures?.[captureKey]?.html || "";

  scanSeriesLinks(html, (id, block) => {
    const serie = ensureSerie(id, null);

    const titre = getTitle(block);

    if (titre && titre !== "Titre inconnu") {
      serie.titre = titre;
    }

    const dedicaces = getDedicaceCount(block);
    const albums = getAlbumCount(block);

    const nbDedicace = Math.max(dedicaces, albums.current, 1);

    serie.nb_dedicace = Math.max(serie.nb_dedicace, nbDedicace);
  });
}

// First parse the complete library as Autre.
parsePossessedCapture("ALL_JAI", "Autre");
parseNonPossessedReadCapture("ALL_JAIPAS_LU", "Autre");

// Then add dedicated album information.
parseDedicaceCapture("ALL_DEDICACE");

// Then parse precise categories to reclassify series.
parsePossessedCapture("BD_JAI", "BD");
parseNonPossessedReadCapture("BD_JAIPAS_LU", "BD");

parsePossessedCapture("Comics_JAI", "Comics");
parseNonPossessedReadCapture("Comics_JAIPAS_LU", "Comics");

parsePossessedCapture("Mangas_JAI", "Mangas");
parseNonPossessedReadCapture("Mangas_JAIPAS_LU", "Mangas");

const lignes = Object.values(seriesMap)
  .filter(serie => serie.id_unique && serie.titre && serie.titre !== "Titre inconnu")
  .sort((a, b) => {
    const catCompare = String(a.categorie).localeCompare(String(b.categorie), "fr");

    if (catCompare !== 0) {
      return catCompare;
    }

    return String(a.titre).localeCompare(String(b.titre), "fr");
  })
  .map((serie) => {
    const albumsPossedes = serie.albums_possedes || 0;
    const albumsLusPossedes = serie.albums_lus_possedes || 0;
    const albumsNonPossedesLu = serie.albums_non_possedes_lu || 0;
    const albumsLusTotal = albumsLusPossedes + albumsNonPossedesLu;

    let statut = "Non classé";

    if (albumsPossedes > 0 && albumsNonPossedesLu > 0) {
      statut = "Partiellement possédé";
    } else if (albumsPossedes > 0) {
      if (albumsLusPossedes >= albumsPossedes) {
        statut = "Possédé et Lu";
      } else if (albumsLusPossedes > 0) {
        statut = "Possédé et Je lis";
      } else {
        statut = "Possédé et Non lu";
      }
    } else if (albumsNonPossedesLu > 0) {
      statut = "Non possédé mais Lu";
    } else {
      statut = "Non possédé et Non lu";
    }

    return {
      id_unique: serie.id_unique,
      titre: serie.titre,
      categorie: serie.categorie || "Autre",
      albums_possedes: albumsPossedes,
      albums_lus: albumsLusTotal,
      statut,
      albums_non_possedes_lu: albumsNonPossedesLu,
      albums_manquants: serie.albums_manquants || 0,
      nb_dedicace: serie.nb_dedicace || 0
    };
  });

return lignes.map(ligne => ({
  json: ligne
}));

// Get all series
const series = $input.all().map(item => item.json);

const stats = {
  "BD": {
    possedes: 0,
    possedes_lus: 0,
    non_possedes_lus: 0,
    dedicaces: 0,
    series_possedees: 0
  },
  "Comics": {
    possedes: 0,
    possedes_lus: 0,
    non_possedes_lus: 0,
    dedicaces: 0,
    series_possedees: 0
  },
  "Mangas": {
    possedes: 0,
    possedes_lus: 0,
    non_possedes_lus: 0,
    dedicaces: 0,
    series_possedees: 0
  },
  "Autre": {
    possedes: 0,
    possedes_lus: 0,
    non_possedes_lus: 0,
    dedicaces: 0,
    series_possedees: 0
  }
};

function toNumber(value) {
  const number = Number(value);
  return Number.isFinite(number) ? number : 0;
}

const statutsPossession = [
  "Possédé et Lu",
  "Possédé et Non lu",
  "Possédé et Je lis",
  "Partiellement possédé"
];

// ======================================================
// MAIN CALCULATION
// ======================================================

for (const s of series) {
  const cat = s.categorie || "Autre";

  if (!stats[cat]) {
    stats[cat] = {
      possedes: 0,
      possedes_lus: 0,
      non_possedes_lus: 0,
      dedicaces: 0,
      series_possedees: 0
    };
  }

  const albumsPossedes = toNumber(s.albums_possedes);
  const albumsLus = toNumber(s.albums_lus);
  const albumsNonPossedesLu = toNumber(s.albums_non_possedes_lu);
  const nbDedicace = toNumber(s.nb_dedicace);

  // Existing calculations
  stats[cat].possedes += albumsPossedes;
  stats[cat].non_possedes_lus += albumsNonPossedesLu;
  stats[cat].dedicaces += nbDedicace;

  const lusEtPossedes = albumsLus - albumsNonPossedesLu;
  stats[cat].possedes_lus += Math.max(lusEtPossedes, 0);

  // Number of owned series
  if (statutsPossession.includes(s.statut)) {
    stats[cat].series_possedees++;
  }
}

// ======================================================
// GOOGLE SHEETS OUTPUT
// ======================================================

const ligneGoogleSheet = {};

for (const cat of ["BD", "Comics", "Mangas", "Autre"]) {
  const catStats = stats[cat];

  const hasData =
    catStats.possedes > 0 ||
    catStats.possedes_lus > 0 ||
    catStats.non_possedes_lus > 0 ||
    catStats.dedicaces > 0 ||
    catStats.series_possedees > 0;

  if (cat === "Autre" && !hasData) {
    continue;
  }

  ligneGoogleSheet[`${cat} - Possédés`] = catStats.possedes;
  ligneGoogleSheet[`${cat} - Possédés et Lus`] = catStats.possedes_lus;
  ligneGoogleSheet[`${cat} - Non possédés et Lus`] = catStats.non_possedes_lus;
  ligneGoogleSheet[`${cat} - Dédicaces`] = catStats.dedicaces;
  ligneGoogleSheet[`${cat} - Séries possédées`] = catStats.series_possedees;
}

return [
  {
    json: ligneGoogleSheet
  }
];

