const resultats = normalizeBrowserlessResult($input.first().json);

if (resultats.statut_session === "invalide") {
  throw new Error(resultats.erreur || "Session Bubble invalide");
}

const seriesMap = {};

function normalizeBrowserlessResult(value) {
  let data = value;

  if (typeof data === "string") {
    data = JSON.parse(data);
  }

  if (data && typeof data.data === "string") {
    data = JSON.parse(data.data);
  } else if (
    data &&
    data.data &&
    typeof data.data === "object" &&
    !data.Toutes &&
    !data.BD &&
    !data.Comics &&
    !data.Mangas
  ) {
    data = data.data;
  }

  return data || {};
}

function decodeHtml(value) {
  return String(value || "")
    .replace(/&nbsp;|&#160;|&#xA0;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/\s+/g, " ")
    .trim();
}

function parseFirstNumber(value) {
  const match = String(value || "").match(/(\d+)/);
  return match ? parseInt(match[1], 10) : 0;
}

function ensureSerie(id) {
  if (!seriesMap[id]) {
    seriesMap[id] = {
      id_unique: id,
      categorie: "Autre",
      titre: "Titre inconnu",
      albums_manquants: 0
    };
  }

  return seriesMap[id];
}

function getTitle(block) {
  const patterns = [
    /<div[^>]*class="[^"]*tw:truncate[^"]*tw:font-bold[^"]*"[^>]*>\s*([^<]+?)\s*<\/div>/i,
    /<div[^>]*class="[^"]*font-bold[^"]*"[^>]*>\s*([^<]+?)\s*<\/div>/i,
    /fw-bold[^>]*>\s*([^<]+?)\s*<\/div>/i
  ];

  for (const pattern of patterns) {
    const match = block.match(pattern);
    if (match) return decodeHtml(match[1]);
  }

  return "Titre inconnu";
}

function getAlbumsManquants(block) {
  const patterns = [
    /<div[^>]*>\s*([0-9]+)\s*<\/div>\s*<div[^>]*>\s*albums?\s+manquants?\s*<\/div>/i,
    /([0-9]+)\s+albums?\s+manquants?/i
  ];

  for (const pattern of patterns) {
    const match = block.match(pattern);
    if (match) return parseFirstNumber(match[1]);
  }

  return 0;
}

function scanSeriesLinks(html, callback) {
  if (!html) return;

  const morceaux = String(html).split('href="/');

  for (let i = 1; i < morceaux.length; i++) {
    const block = morceaux[i];

    const idMatch = block.match(/^[^"\/]+\/serie\/([a-zA-Z0-9]+)"/);
    if (!idMatch) continue;

    callback(idMatch[1], block);
  }
}

function memoriserCategorie(html, categorie) {
  scanSeriesLinks(html, (id) => {
    ensureSerie(id).categorie = categorie;
  });
}

memoriserCategorie(resultats.BD, "BD");
memoriserCategorie(resultats.Comics, "Comics");
memoriserCategorie(resultats.Mangas, "Mangas");

const pagesAAnalyser = [
  resultats.Toutes,
  resultats.BD,
  resultats.Comics,
  resultats.Mangas
];

for (const html of pagesAAnalyser) {
  scanSeriesLinks(html, (id, block) => {
    const serie = ensureSerie(id);

    const titre = getTitle(block);
    if (titre && titre !== "Titre inconnu") {
      serie.titre = titre;
    }

    const albumsManquants = getAlbumsManquants(block);
    if (albumsManquants > 0) {
      serie.albums_manquants = albumsManquants;
    }
  });
}

const seriesExtraites = Object.values(seriesMap);

return seriesExtraites.map(serie => ({
  json: {
    id_unique: serie.id_unique,
    categorie: serie.categorie,
    titre: serie.titre,
    albums_manquants: serie.albums_manquants
  }
}));

const series = $input.all().map(item => item.json);

const stats = {
  "BD": {
    albums_manquants: 0,
    series_souhaitees: 0
  },
  "Comics": {
    albums_manquants: 0,
    series_souhaitees: 0
  },
  "Mangas": {
    albums_manquants: 0,
    series_souhaitees: 0
  },
  "Autre": {
    albums_manquants: 0,
    series_souhaitees: 0
  }
};

function toNumber(value) {
  const number = Number(value);
  return Number.isFinite(number) ? number : 0;
}

for (const s of series) {
  const cat = s.categorie || "Autre";

  if (!stats[cat]) {
    stats[cat] = {
      albums_manquants: 0,
      series_souhaitees: 0
    };
  }

  const albumsManquants = toNumber(s.albums_manquants);

  // Ton calcul actuel
  stats[cat].albums_manquants += albumsManquants;

  // Nouveau : nombre de séries souhaitées
  stats[cat].series_souhaitees++;
}

const ligneGoogleSheet = {};

for (const cat of ["BD", "Comics", "Mangas", "Autre"]) {
  const catStats = stats[cat];

  const hasData =
    catStats.albums_manquants > 0 ||
    catStats.series_souhaitees > 0;

  if (cat === "Autre" && !hasData) {
    continue;
  }

  ligneGoogleSheet[`${cat} - Albums manquants`] =
    catStats.albums_manquants;

  ligneGoogleSheet[`${cat} - Séries souhaitées`] =
    catStats.series_souhaitees;
}

return [
  {
    json: ligneGoogleSheet
  }
];

