parameters.jsCode:
/**
 * NODE: Code in JavaScript6
 * Extracts global metrics and dominant genres, authors, publishers,
 * and total read bubbles.
 */

const input = $input.first().json;

const stats = {
  pages_lues: 0,
  valeur_collection: 0,
  poids_collection: 0,
  series: 0,
  albums: 0,
  bulles_lues: 0
};

// Normalize the HTML.
const htmlClean = String(input.html_brut || "")
  .replace(/[\n\r]/g, " ")
  .replace(/\s+/g, " ");

function decodeHtml(value) {
  return String(value || "")
    .replace(/&nbsp;|&#160;|&#xA0;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .trim();
}

function parseValue(str) {
  if (!str) return 0;

  const clean = String(str)
    .replace(
      /(?:&nbsp;|&#160;|&#xA0;|\s|\u00a0|\u202f)/gi,
      ""
    )
    .replace(/[^0-9.,-]/g, "")
    .replace(",", ".");

  const value = parseFloat(clean);

  return Number.isNaN(value) ? 0 : value;
}

function escapeRegExp(value) {
  return String(value).replace(
    /[.*+?^${}()|[\]\\]/g,
    "\\$&"
  );
}

/**
 * Extracts labels and counters from a dominant-statistics card.
 */
function extractDominantValues(sectionTitle) {
  const values = {};

  const sectionRegex = new RegExp(
    `${escapeRegExp(sectionTitle)}\\s*<\\/div>[\\s\\S]*?` +
      `<div[^>]*class="[^"]*tw:flex-wrap[^"]*"[^>]*>` +
      `([\\s\\S]*?)<\\/div>\\s*<\\/div>`,
    "i"
  );

  const sectionMatch = htmlClean.match(sectionRegex);

  if (!sectionMatch) {
    return values;
  }

  const htmlSection = sectionMatch[1];

  const badgeRegex =
    /<span[^>]*class="[^"]*tw:font-bold[^"]*"[^>]*>([\s\S]*?)<\/span>\s*<span[^>]*class="[^"]*tw:text-text-secondary[^"]*"[^>]*>([\d\s\u00a0\u202f]+)<\/span>/gi;

  let badgeMatch;

  while (
    (badgeMatch = badgeRegex.exec(htmlSection)) !== null
  ) {
    const label = decodeHtml(
      badgeMatch[1].replace(/<[^>]*>/g, "")
    );

    const total =
      parseInt(
        badgeMatch[2].replace(
          /[\s\u00a0\u202f]+/g,
          ""
        ),
        10
      ) || 0;

    if (label) {
      values[label] = total;
    }
  }

  return values;
}


// ============================================================
// 1. Pages read
// ============================================================

const pagesMatch = htmlClean.match(
  /<div[^>]*>([^<]+)<\/div><div>pages\s*lues<\/div>/i
);

if (pagesMatch) {
  stats.pages_lues = Math.round(
    parseValue(pagesMatch[1])
  );
}


// ============================================================
// 2. Collection value
// ============================================================

const valeurMatch = htmlClean.match(
  /<div>Ma\s*collection\s*vaut\s*\(neuve\)<\/div><div[^>]*>([^<]+)<\/div>/i
);

if (valeurMatch) {
  stats.valeur_collection = Number(
    parseValue(valeurMatch[1]).toFixed(2)
  );
}


// ============================================================
// 3. Collection weight
// ============================================================

const poidsMatch = htmlClean.match(
  /<div>Ma\s*collection\s*pèse<\/div><div[^>]*>([^<]+)<\/div>/i
);

if (poidsMatch) {
  stats.poids_collection = Number(
    parseValue(poidsMatch[1]).toFixed(2)
  );
}


// ============================================================
// 4. Total series
// ============================================================

const seriesMatch = htmlClean.match(
  /<div[^>]*>([\d]+)<\/div><div[^>]*>séries<\/div>/i
);

if (seriesMatch) {
  stats.series = parseInt(
    seriesMatch[1],
    10
  );
}


// ============================================================
// 5. Total albums
// ============================================================

const albumsMatch = htmlClean.match(
  /<div[^>]*>([\d]+)<\/div><div[^>]*>albums<\/div>/i
);

if (albumsMatch) {
  stats.albums = parseInt(
    albumsMatch[1],
    10
  );
}


// ============================================================
// 6. Bulles lues
// ============================================================

const bullesLuesMatch = htmlClean.match(
  /<div[^>]*class="[^"]*tw:font-bold[^"]*"[^>]*>\s*([\d\s\u00a0\u202f]+)\s*<\/div>\s*<div[^>]*>\s*bulles\s*lues\s*<\/div>/i
);

if (bullesLuesMatch) {
  stats.bulles_lues =
    parseInt(
      bullesLuesMatch[1].replace(
        /[\s\u00a0\u202f]+/g,
        ""
      ),
      10
    ) || 0;
}


// ============================================================
// Backup rule for bulles lues
// ============================================================

if (stats.bulles_lues === 0) {
  const backupBullesLues = htmlClean.match(
    /([\d\s\u00a0\u202f]+)<\/div>\s*<div[^>]*>\s*bulles\s*lues\s*<\/div>/i
  );

  if (backupBullesLues) {
    stats.bulles_lues =
      parseInt(
        backupBullesLues[1].replace(
          /[\s\u00a0\u202f]+/g,
          ""
        ),
        10
      ) || 0;
  }
}


// ============================================================
// Backup rule for pages
// ============================================================

if (stats.pages_lues === 0) {
  const backupPages = htmlClean.match(
    /tw:font-bold[^>]*>([\d]+)<\/div><div>pages lues/i
  );

  if (backupPages) {
    stats.pages_lues = parseInt(
      backupPages[1],
      10
    );
  }
}


// ============================================================
// Backup rule for collection value
// ============================================================

if (stats.valeur_collection === 0) {
  const backupValeur = htmlClean.match(
    /Ma collection vaut \(neuve\).+?leading-\[[^\]]+\]">([^<]+)/i
  );

  if (backupValeur) {
    stats.valeur_collection = Number(
      parseValue(backupValeur[1]).toFixed(2)
    );
  }
}


// ============================================================
// Extract dominant statistics
// ============================================================

const genresDominants =
  extractDominantValues("Genres dominants");

const auteursDominants =
  extractDominantValues("Auteurs dominants");

const editeursDominants =
  extractDominantValues("Éditeurs dominants");


// ============================================================
// Combined structured output
// ============================================================

const donneesDominantes = {
  "Bulles lues": stats.bulles_lues || 0,
  Genre: genresDominants,
  Auteurs: auteursDominants,
  "Éditeurs": editeursDominants
};


// ============================================================
// Final output
// ============================================================

return [
  {
    json: {
      pages_lues: stats.pages_lues || 0,

      valeur_collection:
        stats.valeur_collection || 0,

      poids_collection:
        stats.poids_collection || 0,

      series:
        stats.series || 0,

      albums:
        stats.albums || 0,

      bulles_lues:
        stats.bulles_lues || 0,

      // Kept for compatibility with the existing workflow.
      genres_et_sous_genres:
        donneesDominantes,

      // Explicit output as well.
      donneesDominantes,

      statut_sync: "OK"
    }
  }
];

