    code: `
export default async function({ page, context }) {
  const sleep = (ms) => new Promise(resolve => setTimeout(resolve, ms));

  await page.setUserAgent(
    'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36'
  );

  function normalizeCookies(rawCookies) {
    if (!rawCookies) return [];

    if (Array.isArray(rawCookies)) return rawCookies;

    if (typeof rawCookies === 'string') {
      try {
        const parsed = JSON.parse(rawCookies);
        return Array.isArray(parsed) ? parsed : [];
      } catch (error) {
        return [];
      }
    }

    return [];
  }

  const cookies = normalizeCookies(context.cookies)
    .filter(cookie => cookie && cookie.name && typeof cookie.value !== 'undefined')
    .map(cookie => {
      const cleanCookie = { ...cookie };

      if (cleanCookie.sameSite === 'no_restriction') {
        cleanCookie.sameSite = 'None';
      }

      if (cleanCookie.sameSite === 'unspecified') {
        delete cleanCookie.sameSite;
      }

      delete cleanCookie.storeId;
      delete cleanCookie.hostOnly;
      delete cleanCookie.session;

      return cleanCookie;
    });

  if (cookies.length > 0) {
    await page.setCookie(...cookies);
  }

  async function openBasePage() {
    await page.goto(context.url, {
      waitUntil: 'domcontentloaded',
      timeout: 0
    });

    await sleep(10000);

    try {
      await page.waitForFunction(() => {
        const text = document.body ? document.body.innerText : '';

        return (
          text.includes('Pile à lire') ||
          text.includes('Mes BD') ||
          text.includes('J\\'ai') ||
          text.includes('J\\'ai pas')
        );
      }, {
        timeout: 30000
      });
    } catch (error) {
      // Continue, session is checked after.
    }
  }

  async function checkSession() {
    return await page.evaluate(() => {
      const text = document.body ? document.body.innerText : '';

      const hasCollection =
        text.includes('Pile à lire') ||
        text.includes('Ma collection') ||
        text.includes('Mes BD') ||
        text.includes('J\\'ai') ||
        text.includes('J\\'ai pas');

      const hasLogin =
        text.includes('Connexion') ||
        text.includes('Se connecter') ||
        text.includes('Connectez-vous');

      return {
        hasCollection,
        hasLogin,
        preview: text.slice(0, 2000)
      };
    });
  }

  async function getCheckedStates() {
    return await page.evaluate(() => {
      function normalizeText(value) {
        return String(value || '')
          .replace(/[’´]/g, "'")
          .replace(/\\s+/g, ' ')
          .trim()
          .toLowerCase();
      }

      function isLabelCheckedByText(labelText) {
        const target = normalizeText(labelText);
        const labels = Array.from(document.querySelectorAll('label'));

        const label = labels.find(element => normalizeText(element.textContent) === target);

        if (!label) return null;

        const input = label.querySelector('input[type="checkbox"]');
        const hasCheckIcon = label.querySelector('svg') !== null;
        const hasSuccessClass =
          label.innerHTML.includes('border-success') ||
          label.innerHTML.includes('bg-success') ||
          label.innerHTML.includes('tw:text-success');

        return Boolean((input && input.checked) || hasCheckIcon || hasSuccessClass);
      }

      function isInputCheckedById(id) {
        const input = document.getElementById(id);

        if (!input) return null;

        const label = input.closest('label');
        const hasCheckIcon = label ? label.querySelector('svg') !== null : false;
        const hasSuccessClass = label
          ? (
              label.innerHTML.includes('border-success') ||
              label.innerHTML.includes('bg-success') ||
              label.innerHTML.includes('tw:text-success')
            )
          : false;

        return Boolean(input.checked || hasCheckIcon || hasSuccessClass);
      }

      return {
        checkBd: isInputCheckedById('checkBd'),
        checkComics: isInputCheckedById('checkComics'),
        checkMangas: isInputCheckedById('checkMangas'),
        lu: isLabelCheckedByText('Lu'),
        nonLu: isLabelCheckedByText('Non lu'),
        jai: isLabelCheckedByText("J'ai"),
        jaiPas: isLabelCheckedByText("J'ai pas"),
        prete: isLabelCheckedByText('Prêté'),
        dedicace: isLabelCheckedByText('Dédicacé'),
        editionOriginale: isLabelCheckedByText('Edition Originale')
      };
    });
  }

  async function setCheckboxById(id, desiredState) {
    const result = await page.evaluate((checkboxId, desired) => {
      const input = document.getElementById(checkboxId);

      if (!input) {
        return {
          found: false,
          changed: false,
          checkedBefore: null
        };
      }

      const label = input.closest('label');

      const hasCheckIcon = label ? label.querySelector('svg') !== null : false;
      const hasSuccessClass = label
        ? (
            label.innerHTML.includes('border-success') ||
            label.innerHTML.includes('bg-success') ||
            label.innerHTML.includes('tw:text-success')
          )
        : false;

      const checkedBefore = Boolean(input.checked || hasCheckIcon || hasSuccessClass);

      if (checkedBefore !== desired) {
        if (label) {
          label.scrollIntoView({ block: 'center' });
          label.click();
        } else {
          input.scrollIntoView({ block: 'center' });
          input.click();
        }

        return {
          found: true,
          changed: true,
          checkedBefore
        };
      }

      return {
        found: true,
        changed: false,
        checkedBefore
      };
    }, id, desiredState);

    await sleep(500);
    return result;
  }

  async function setCheckboxByText(text, desiredState) {
    const result = await page.evaluate((targetText, desired) => {
      function normalizeText(value) {
        return String(value || '')
          .replace(/[’´]/g, "'")
          .replace(/\\s+/g, ' ')
          .trim()
          .toLowerCase();
      }

      const target = normalizeText(targetText);
      const labels = Array.from(document.querySelectorAll('label'));

      const label = labels.find(element => normalizeText(element.textContent) === target);

      if (!label) {
        return {
          found: false,
          changed: false,
          checkedBefore: null
        };
      }

      const input = label.querySelector('input[type="checkbox"]');

      const hasCheckIcon = label.querySelector('svg') !== null;
      const hasSuccessClass =
        label.innerHTML.includes('border-success') ||
        label.innerHTML.includes('bg-success') ||
        label.innerHTML.includes('tw:text-success');

      const checkedBefore = Boolean((input && input.checked) || hasCheckIcon || hasSuccessClass);

      if (checkedBefore !== desired) {
        label.scrollIntoView({ block: 'center' });
        label.click();

        return {
          found: true,
          changed: true,
          checkedBefore
        };
      }

      return {
        found: true,
        changed: false,
        checkedBefore
      };
    }, text, desiredState);

    await sleep(500);
    return result;
  }

  async function applyExactFilters(config) {
    await page.evaluate(() => window.scrollTo(0, 0));
    await sleep(800);

    await setCheckboxById('checkBd', config.category === 'BD');
    await setCheckboxById('checkComics', config.category === 'Comics');
    await setCheckboxById('checkMangas', config.category === 'Mangas');

    await setCheckboxByText('Prêté', false);
    await setCheckboxByText('Dédicacé', false); // Désactivé pour la PAL

    await setCheckboxByText('Lu', Boolean(config.lu));
    await setCheckboxByText('Non lu', false);

    await setCheckboxByText("J'ai", false); // Désactivé pour la PAL
    await setCheckboxByText("J'ai pas", Boolean(config.jaiPas));

    await setCheckboxByText('Edition Originale', false);

    await sleep(4000);
  }

  async function autoScrollFullList(maxScrolls = 90) {
    await page.evaluate(async (max) => {
      await new Promise((resolve) => {
        let unchangedCount = 0;
        let lastHeight = 0;
        let lastSeriesCount = 0;
        let scrollCount = 0;

        const timer = setInterval(() => {
          window.scrollBy(0, 1400);
          scrollCount++;

          const currentHeight = document.body.scrollHeight;
          const currentSeriesCount = document.querySelectorAll('a[href*="/serie/"]').length;
          const nearBottom = window.innerHeight + window.scrollY >= document.body.scrollHeight - 20;

          if (
            nearBottom &&
            currentHeight === lastHeight &&
            currentSeriesCount === lastSeriesCount
          ) {
            unchangedCount++;
          } else {
            unchangedCount = 0;
          }

          lastHeight = currentHeight;
          lastSeriesCount = currentSeriesCount;

          if (unchangedCount >= 6 || scrollCount >= max) {
            clearInterval(timer);
            resolve();
          }
        }, 250);
      });
    }, maxScrolls);

    await sleep(1200);
  }

  async function getCounterFromBodyText() {
    return await page.evaluate(() => {
      const text = document.body ? document.body.innerText : '';

      const normalized = text
        .replace(/\\u00a0/g, ' ')
        .replace(/\\u202f/g, ' ')
        .replace(/\\s+/g, ' ')
        .trim();

      const match = normalized.match(/([0-9]+)\\s*séries\\s*\\/\\s*([0-9]+)\\s*albums?/i);

      return {
        series: match ? parseInt(match[1], 10) : 0,
        albums: match ? parseInt(match[2], 10) : 0,
        preview: normalized.slice(0, 1200)
      };
    });
  }

  async function captureList(key, config) {
    await applyExactFilters(config);
    await autoScrollFullList(config.maxScrolls || 90);

    const html = await page.content();

    const text = await page.evaluate(() => {
      return document.body ? document.body.innerText : '';
    });

    const counter = await getCounterFromBodyText();
    const checkedStates = await getCheckedStates();

    return {
      key,
      category: config.category,
      lu: Boolean(config.lu),
      jai: Boolean(config.jai),
      jaiPas: Boolean(config.jaiPas),
      dedicace: Boolean(config.dedicace),
      series: counter.series,
      albums: counter.albums,
      html,
      text,
      checkedStates,
      preview: counter.preview
    };
  }

  await openBasePage();

  const session = await checkSession();

  if (!session.hasCollection && session.hasLogin) {
    return {
      statut_session: 'invalide',
      erreur: 'Cookie Bubble expiré ou utilisateur déconnecté',
      debug: session
    };
  }

  // J'ai retiré toutes les configurations qui ne concernent pas les albums "Non possédés et Lus"
  const configs = [
    {
      key: 'ALL_JAIPAS_LU',
      category: 'Autre',
      jai: false,
      jaiPas: true,
      lu: true,
      dedicace: false,
      maxScrolls: 90
    },
    {
      key: 'BD_JAIPAS_LU',
      category: 'BD',
      jai: false,
      jaiPas: true,
      lu: true,
      dedicace: false,
      maxScrolls: 40
    },
    {
      key: 'Comics_JAIPAS_LU',
      category: 'Comics',
      jai: false,
      jaiPas: true,
      lu: true,
      dedicace: false,
      maxScrolls: 40
    },
    {
      key: 'Mangas_JAIPAS_LU',
      category: 'Mangas',
      jai: false,
      jaiPas: true,
      lu: true,
      dedicace: false,
      maxScrolls: 50
    }
  ];

  const captures = {};

  for (const config of configs) {
    captures[config.key] = await captureList(config.key, config);
  }

  return {
    statut_session: 'valide',
    mode_extraction: 'pile_a_lire_uniquement',
    captures,
    debug: {
      session,
      resume: Object.fromEntries(
        Object.entries(captures).map(([key, value]) => [
          key,
          {
            series: value.series,
            albums: value.albums,
            dedicace: value.dedicace,
            checkedStates: value.checkedStates,
            preview: value.preview
          }
        ])
      )
    }
  };
}
    `,
    context: {
      url: $('Configuration Globale').first().json.Bubblebd_PAL,
      cookies: $('Configuration Globale').first().json.cookie_bubble
    }
  }
}}
